def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        base = 18.0 if hp > 3 else 45.0
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    urgent_opponents = 0
    rich_opponents = 0
    weak_opponents = 0

    for opp in alive:
        if opp.get('budget', 0) >= 200:
            rich_opponents += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opponents += 1
        if opp.get('hp', 10) <= 2:
            weak_opponents += 1
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    contested = len(alive) >= 3
    low_supply = supply <= 17.0
    high_supply = supply >= 22.0
    my_urgent = hp <= 3 or no_water_days >= 1
    my_critical = hp <= 2 or no_water_days >= 2

    bid = 0.0

    if my_critical:
        bid = max(95.0, highest_prev + 3.0, avg_prev + 6.0)
    elif my_urgent:
        bid = max(78.0, highest_prev + 2.0 if highest_prev > 0 else 82.0)
    else:
        if high_supply and weak_opponents >= 1:
            bid = 24.0
        elif high_supply:
            bid = 32.0 if contested else 26.0
        elif low_supply:
            if highest_prev >= 120.0:
                bid = highest_prev + 2.0
            else:
                bid = max(62.0, avg_prev + 4.0 if avg_prev > 0 else 66.0)
        else:
            if highest_prev >= 145.0:
                bid = 52.0 if hp > 4 else 88.0
            elif highest_prev >= 120.0:
                bid = highest_prev + 1.5 if hp <= 4 else 58.0
            elif highest_prev > 0:
                bid = max(48.0, avg_prev + 3.0)
            else:
                bid = 44.0

    if rich_opponents >= 2 and low_supply and not my_urgent:
        bid = max(bid, 68.0)
    if urgent_opponents >= 2 and hp > 4 and not my_urgent:
        bid = min(bid, 40.0)

    if day >= 8 and hp > 4 and budget < 120:
        bid = min(bid, 38.0)
    if day >= 8 and my_urgent:
        bid = max(bid, 90.0)

    if budget < 50:
        bid = min(bid, max(12.0, budget))
    elif budget < 90 and not my_urgent:
        bid = min(bid, 36.0)

    bid = max(0.0, min(float(budget), float(bid)))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return min(budget, DAILY_SALARY * 0.4)

    # Read yesterday bids only from previous_trace
    prev_bids = []
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # If we have no signal, use a conservative baseline
    if not prev_bids:
        base = DAILY_SALARY * 0.55
        if hp <= 2 or no_water_days >= 2:
            base = DAILY_SALARY * 0.85
        return min(budget, base)

    highest_prev_bid = max(prev_bids)
    second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid

    # Estimate how aggressive the market is: if someone was bidding near/above salary, expect high contention.
    high_contention = highest_prev_bid >= DAILY_SALARY * 0.85

    # Our goal: bid enough to secure water without matching the highest bidder.
    # Use a target near the second-highest, with a small bump when our hp is fragile.
    if high_contention:
        target = second_prev_bid + 5.0
    else:
        # Moderate contention: stay below the leader but above our baseline.
        target = max(DAILY_SALARY * 0.5, (highest_prev_bid + second_prev_bid) / 2.0)

    # Scale based on our urgency
    urgency = 0
    if hp <= 2:
        urgency = 2
    elif hp <= 4:
        urgency = 1
    if no_water_days >= 2:
        urgency = max(urgency, 2)

    if urgency == 2:
        target *= 1.10
    elif urgency == 1:
        target *= 1.05

    # Supply-aware adjustment: higher supply reduces need to overbid.
    # supply is in [15,25]
    supply_frac = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    # When supply is high, slightly reduce target.
    target *= (0.98 - 0.10 * supply_frac)

    # Hard caps to prevent bankrupting ourselves
    # Never bid more than a fraction of budget; keep some reserve for later days.
    reserve_frac = 0.25 if day <= 5 else 0.15
    max_affordable = budget * (1.0 - reserve_frac)

    # Also keep within reasonable bidding range relative to daily salary
    target = min(target, DAILY_SALARY * 1.2)

    bid = min(max_affordable, max(0.0, target))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > int(EPISODE_DAYS / 3):
                return min(my_status['budget'], DAILY_SALARY * 0.3)
            return min(my_status['budget'], DAILY_SALARY * 0.95)

        return min(my_status['budget'], max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))

    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.9)
    elif my_status['hp'] <= int(EPISODE_DAYS / 2):
        return min(my_status['budget'], DAILY_SALARY * 0.7)
    else:
        return min(my_status['budget'], DAILY_SALARY * 0.55)
